corrected_code:
def get_contract_summary(request, contract_uuid):
    latest_milestone_payout = Subquery(
        ContractMilestone.objects.filter(contract_id=OuterRef('id'))
        .order_by('-due_date')
        .values('payout_amount')[:1]
    )
    contract = Contract.objects.filter(
        Q(client=request.user) | Q(contractor=request.user),
        uuid=contract_uuid
    ).annotate(next_payout=latest_milestone_payout).first()
    if not contract:
        return HttpResponseNotFound()
    return JsonResponse({'title': contract.title, 'value': str(contract.total_value), 'next_payout': str(contract.next_payout)})
